window.kbPageData["views/entry/k-2855a7e496b811b6"] = {"key":"entry/k-2855a7e496b811b6","state":{"route":"entry/k-2855a7e496b811b6"},"node":{"id":"k-2855a7e496b811b6","mode":"k","title":"集合的互斥分区计数","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["集合人数等于其所包含的各互斥区域人数之和","集合人数等于其互斥分区人数之和"],"qs":["国考 2024 行政执法 行测#67","国考 2025 地市级 行测#69"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":2,"repeatPositions":0,"directorySummary":"把一个集合划分为互不重叠且合起来覆盖全体的若干部分，集合的总人数等于各部分人数之和。","review":{"definition":"把一个集合划分为互不重叠且合起来覆盖全体的若干部分，集合的总人数等于各部分人数之和。","explanation":"全单位三项认证都没有的有65×20%=13人。「没有甲认证」与「有乙认证」两组人数相等，且都包含仅有乙、仅有乙和丙这两部分。消去这两部分后，前一组剩下仅有丙的3人和三项都没有的13人，后一组剩下仅有甲和乙的人以及三项都有的6人。因此仅有甲和乙的有3+13−6=10人，选A。","references":[],"evidence":"没有甲认证的职工与有乙认证的职工人数一样多","disposition":"独立词条","basis":"据原题和解析编释。","title":"集合的互斥分区计数","related":[],"examFocus":{"国考 2024 行政执法 行测#67":"按掌握语言的组合划分互斥区域，结合包含关系和两个“一半”的条件，确定会法语的人数应汇总哪些区域。","国考 2025 地市级 行测#69":"用至少持有一项认证的比例确定三项都没有的人数，再按互斥区域比较“没有甲”和“有乙”两组的构成。"}},"readings":[{"origin":"k-2855a7e496b811b6","title":"集合的互斥分区计数","qs":["国考 2025 地市级 行测#69"],"definition":"把一个集合划分为互不重叠且合起来覆盖全体的若干部分，集合的总人数等于各部分人数之和。","explanation":"全单位三项认证都没有的有65×20%=13人。「没有甲认证」与「有乙认证」两组人数相等，且都包含仅有乙、仅有乙和丙这两部分。消去这两部分后，前一组剩下仅有丙的3人和三项都没有的13人，后一组剩下仅有甲和乙的人以及三项都有的6人。因此仅有甲和乙的有3+13−6=10人，选A。","evidence":"没有甲认证的职工与有乙认证的职工人数一样多","doubt":"","references":[]},{"origin":"k-558a3350b0f6e48a","title":"集合的互斥分区计数","qs":["国考 2024 行政执法 行测#67"],"definition":"把有限集合划分为彼此不重叠且合起来覆盖全体的若干部分，总人数等于各部分人数之和。","explanation":"会俄语者都在英语集合内，且其中一半会法语，因此三语都会的50人对应只会俄语和英语的50人。在只会两种语言的100人中，其余50人只会英语和法语。会英语且会法语的共100人，占会英语者的一半，所以会英语的共200人，其中只会英语的有50人。只会一种语言的150人扣除这50人，剩下100人只会法语。把只会法语、只会英语和法语、三语都会这三个互斥分区相加，得到会法语的共有200人。","evidence":"会法语的学生有100+50+50=200人","doubt":"","references":[]}]},"questions":{"国考 2024 行政执法 行测#67":{"paper":"国考 2024 行政执法 行测","n":67,"mod":"数量关系","src":["dfddc59dc6e7d9da5d71.pdf",12],"asrc":["6493f3a6a55c38431852.pdf",20],"card":"c8340eb2a10cbcfa2e1f166b","links":[{"id":"k-2855a7e496b811b6","role":"解题依据","why":"只会法语、只会英语和法语以及三种语言都会的分区合计覆盖法语集合。"}]},"国考 2025 地市级 行测#69":{"paper":"国考 2025 地市级 行测","n":69,"mod":"数量关系","src":["31f401e91aef8d11365d.pdf",12],"asrc":["8cece062c7c079b53130.pdf",22],"card":"af66575f1af313d73df08c8b","links":[{"id":"k-2855a7e496b811b6","role":"解题依据","why":"将两组人分别拆成互不重叠的区域后，可按区域求和并找出两组的共有项。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-2855a7e496b811b6":[["国考 2024 行政执法 行测#67"],["国考 2025 地市级 行测#69"]]}};
